// frontend/src/App.js

import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [logs, setLogs] = useState([]);
  const [status, setStatus] = useState('Loading...');

  useEffect(() => {
    // This function runs once when the component loads
    const fetchLogs = async () => {
      try {
        const response = await axios.get('http://localhost:5001/api/logs');
        setLogs(response.data);
        if (response.data.length === 0) {
          setStatus('No logs found in the database. Add some to the logs folder!');
        }
      } catch (error) {
        console.error("Error fetching logs:", error);
        setStatus('Could not connect to the backend. Is the Flask server running?');
      }
    };

    fetchLogs();
  }, []); // The empty array ensures this effect runs only once

  const formatTimestamp = (unixTimestamp) => {
    // Converts Unix timestamp to a readable local date and time
    return new Date(unixTimestamp * 1000).toLocaleString();
  };

  const formatDuration = (seconds) => {
    // Converts seconds to a MM:SS format
    if (seconds < 0) return '00:00';
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = Math.floor(seconds % 60);
    return `${String(minutes).padStart(2, '0')}:${String(remainingSeconds).padStart(2, '0')}`;
  };

  return (
    <div className="bg-gray-900 text-white min-h-screen font-sans">
      <div className="container mx-auto p-4 md:p-8">
        <header className="mb-8">
          <h1 className="text-4xl font-bold text-cyan-400">Jeep Diagnostics Dashboard</h1>
          <p className="text-gray-400">Log File Index</p>
        </header>

        <main className="bg-gray-800 rounded-lg shadow-xl p-4">
          <div className="overflow-x-auto">
            {logs.length > 0 ? (
              <table className="w-full text-left">
                <thead className="border-b-2 border-cyan-500">
                  <tr>
                    <th className="p-3">Log File</th>
                    <th className="p-3">Trip Start Time</th>
                    <th className="p-3 text-right">Duration (min:sec)</th>
                  </tr>
                </thead>
                <tbody>
                  {logs.map((log) => (
                    <tr key={log.log_id} className="border-b border-gray-700 hover:bg-gray-700/50">
                      <td className="p-3 font-mono">{log.file_name}</td>
                      <td className="p-3">{formatTimestamp(log.start_timestamp)}</td>
                      <td className="p-3 text-right font-mono">{formatDuration(log.trip_duration_seconds)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <p className="text-center text-gray-400 py-8">{status}</p>
            )}
          </div>
        </main>

        <footer className="text-center mt-8 text-gray-500 text-sm">
            <p>Jeep Log Processor v0.9.0</p>
        </footer>
      </div>
    </div>
  );
}

export default App;
